const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const content = buffer.toString('utf8');
const lines = content.split(/\r?\n/).filter((line) => line.trim().length > 0);
const records = lines.map((line, index) => {
  try {
    return JSON.parse(line);
  } catch (error) {
    throw new Error(`Invalid JSONL at line ${index + 1}: ${error.message}`);
  }
});

const required = [
  'policy_code',
  'category',
  'canonical_question',
  'answer_text',
  'paraphrases',
  'conditions',
  'effective_from',
  'effective_to',
  'version',
  'source_title',
  'source_section',
  'owner',
  'approved',
  'sensitivity',
  'synthetic'
];

if (records.length !== 100) {
  throw new Error(`Dataset must contain exactly 100 records, found ${records.length}.`);
}

const codes = new Set();
const categories = new Set();
for (const record of records) {
  for (const field of required) {
    if (!(field in record)) throw new Error(`${record.policy_code || 'UNKNOWN'} missing required field ${field}.`);
  }
  if (!/^HR-\d{3}$/.test(record.policy_code)) throw new Error(`${record.policy_code} does not match HR-001 format.`);
  if (codes.has(record.policy_code)) throw new Error(`Duplicate policy_code ${record.policy_code}.`);
  codes.add(record.policy_code);
  categories.add(record.category);
  if (!Array.isArray(record.paraphrases) || record.paraphrases.length < 3) throw new Error(`${record.policy_code} must have at least 3 paraphrases.`);
  if (record.synthetic !== true) throw new Error(`${record.policy_code} synthetic must be true.`);
  if (record.approved !== true) throw new Error(`${record.policy_code} approved must be true for this demo dataset.`);
  if (record.source_title !== 'Sentetik İK Politikası') throw new Error(`${record.policy_code} has invalid source_title.`);
  const from = Date.parse(record.effective_from);
  if (Number.isNaN(from)) throw new Error(`${record.policy_code} effective_from is invalid.`);
  if (record.effective_to !== null) {
    const to = Date.parse(record.effective_to);
    if (Number.isNaN(to) || to < from) throw new Error(`${record.policy_code} effective_to is before effective_from.`);
  }
}

if (categories.size < 15) throw new Error(`Dataset must contain at least 15 categories, found ${categories.size}.`);

return [{
  json: {
    dataset_total: records.length,
    unique_policy_codes: codes.size,
    category_count: categories.size,
    records_json: JSON.stringify(records)
  }
}];
